#!/usr/bin/env bash
# Run the upstream purescript repo's `tests/purs/optimize/` golden tests
# against our codegen.
#
# For each `optimize/Foo.purs` + `optimize/Foo.out.js` pair upstream:
#   1. Compile Foo.purs with purs to produce corefn.json
#   2. Run our codegen on the corefn.json
#   3. Compare against Foo.out.js
#
# Strips the "// Generated by purs version" prefix from purs's output before
# comparing. With SEMANTIC=1, also normalizes `$N` fresh-name numbering.
#
# Pulls/updates the purescript repo if missing.

set -e

PROJECT=/Users/avinashverma/purescriptCodeGen
SAMPLE=$PROJECT/sample-purs
OUT=/tmp/pursjs-upstream-tests
TESTS_DIR=$PROJECT/tests/upstream/optimize

if [ ! -d "$TESTS_DIR" ]; then
  echo "FAIL: $TESTS_DIR not found." >&2
  echo "Run bin/sync-upstream-tests.sh to populate the local test set." >&2
  exit 1
fi

# 2. Build our codegen
echo "Building our codegen..."
cd "$PROJECT"
spago build >/dev/null 2>&1 || { spago build; exit 1; }

# Pre-warm node's ESM module cache
node --input-type=module -e "import('./output/PursJS.Main/index.js')" 2>/dev/null || true

mkdir -p "$OUT"

# 3. Set up a workdir with prelude and the test as sources
WORKDIR=$(mktemp -d -t pursjs-upstream-XXXXXX)
trap "rm -rf $WORKDIR" EXIT

# Pull in ALL installed prelude-package sources from sample-purs/.spago/
SOURCES_BASE=()
for pkgdir in "$SAMPLE"/.spago/p/*/; do
  if [ -d "$pkgdir/src" ]; then
    SOURCES_BASE+=("$pkgdir/src/**/*.purs")
  fi
done

ok=0
diff=0
fail=0
failed_names=()
differed_names=()

# normalize() — renumber `$N` placeholders to 0..M in order of first appearance.
normalize() {
  python3 -c '
import sys, re
text = sys.stdin.read()
pat = re.compile(r"\$\d+|\$tco_done\d+")
mapping = {}
counter = [0]
def repl(m):
    name = m.group(0)
    if name not in mapping:
        prefix = "$tco_done" if name.startswith("$tco_done") else "$"
        mapping[name] = prefix + str(counter[0])
        counter[0] += 1
    return mapping[name]
sys.stdout.write(pat.sub(repl, text))
'
}

for purs in "$TESTS_DIR"/*.purs; do
  name=$(basename "$purs" .purs)
  expected="$TESTS_DIR/$name.out.js"
  [ -f "$expected" ] || continue

  # If the test has a sibling Foreign.js/<Name>.js, include it
  foreign_js=""
  case "$name" in
    Foreign) foreign_js="$TESTS_DIR/Foreign.js" ;;
  esac

  # Set up a fresh workdir per test
  rm -rf "$WORKDIR/output"
  cp "$purs" "$WORKDIR/$name.purs"
  if [ -n "$foreign_js" ] && [ -f "$foreign_js" ]; then
    cp "$foreign_js" "$WORKDIR/$name.js"
  fi

  # Compile with purs
  pushd "$WORKDIR" >/dev/null
  if ! purs compile --codegen js,corefn -o output "${SOURCES_BASE[@]}" "$name.purs" 2>/tmp/purs.err; then
    failed_names+=("$name (purs compile)")
    fail=$((fail+1))
    popd >/dev/null
    continue
  fi
  popd >/dev/null

  corefn="$WORKDIR/output/Main/corefn.json"
  if [ ! -f "$corefn" ]; then
    failed_names+=("$name (no corefn)")
    fail=$((fail+1))
    continue
  fi

  # Run our codegen. The upstream optimize fixtures preserve leading line
  # comments from the .purs source (the Haskell test runs purs with `--comments`),
  # so we pass `--with-comments` to match.
  ours=$(node --input-type=module -e "
import { main } from '$PROJECT/output/PursJS.Main/index.js';
process.argv = [process.argv[0], 'main', '$corefn', '--with-comments'];
main();
" 2>/dev/null) || {
    failed_names+=("$name (codegen error)")
    fail=$((fail+1))
    continue
  }

  # Compare against expected — strip prefix comment lines
  expected_stripped=$(grep -v -E '^(// Generated by|//# sourceMappingURL=)' "$expected")
  ours_stripped=$(echo "$ours" | grep -v -E '^(// Generated by|//# sourceMappingURL=)')

  if [ "${SEMANTIC:-0}" = "1" ]; then
    expected_stripped=$(printf "%s\n" "$expected_stripped" | normalize)
    ours_stripped=$(printf "%s\n" "$ours_stripped" | normalize)
  fi

  if [ "$ours_stripped" = "$expected_stripped" ]; then
    ok=$((ok+1))
    echo "OK   $name"
  else
    diff=$((diff+1))
    differed_names+=("$name")
    printf "%s\n" "$expected_stripped" > "$OUT/$name.expected.js"
    printf "%s\n" "$ours_stripped" > "$OUT/$name.ours.js"
    echo "DIFF $name"
  fi
done

echo ""
echo "Upstream optimizer tests: $ok pass, $diff differ, $fail errored"
if [ ${#differed_names[@]} -gt 0 ] && [ "${VERBOSE:-0}" = "1" ]; then
  echo ""
  echo "Diffs saved under $OUT/<name>.{expected,ours}.js"
  for n in "${differed_names[@]:0:5}"; do
    echo ""
    echo "=== $n ==="
    diff -u "$OUT/$n.expected.js" "$OUT/$n.ours.js" | head -25
  done
fi
[ ${#failed_names[@]} -eq 0 ] || { echo "Errored: ${failed_names[*]}"; exit 1; }
